    correction: [{"quoi":"القاعدة","math":"القسمة على عدد موجب لا تغيّر اتّجاه المتراجحة"},{"quoi":"العددان موجبان","math":"<span dir=\"ltr\" class=\"expr\">0 &lt; s</span>"},{"quoi":"و كذلك","math":"<span dir=\"ltr\" class=\"expr\">0 &lt; t</span>"},{"quoi":"ننطلق من المقارنة","math":"<span dir=\"ltr\" class=\"expr\">s &lt; t</span>"},{"quoi":"نقسم الطرفين على t الموجب","math":"الكسر <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">s</span><span class=\"den\">t</span></span></span> يصبح أصغر من 1"},{"quoi":"نقسم نفس المتراجحة على s الموجب","math":"الكسر <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">t</span><span class=\"den\">s</span></span></span> يصبح أكبر من 1"},{"quoi":"النتيجة","math":"الترتيب التصاعدي هو <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">s</span><span class=\"den\">t</span></span></span> ثمّ 1 ثمّ <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">t</span><span class=\"den\">s</span></span></span>"}],
